{{ config(
            materialized='table',
                post_hook={
                    "sql": "CREATE OR REPLACE TABLE ANDAMEN_DB.MAPLEMONK.TAX_SALES_AND_RETURNS_FACT_ITEMS AS WITH sales_data AS ( SELECT TRY_TO_DATE(\"Invoice Date\", \'YYYY-MM-DD HH24:MI:SS\') AS transaction_date, NULL AS return_date, \"MP Name\" AS marketplace_name, \"Sales Channel\" AS sales_channel, \"Component SKU Name\" AS product_name, \"Component SKU Brand\" AS brand, \"Component SKU Category\" AS category, \"Suborder No\" AS suborder_id, TRY_TO_NUMBER(\"Item Quantity\") AS quantity, TRY_TO_NUMBER(\"Component SKU MRP\") AS mrp, TRY_TO_NUMBER(\"Selling Price\") AS selling_price, TRY_TO_NUMBER(\"Component SKU Cost\") AS cost_price, TRY_TO_NUMBER(\"Taxable Value\") AS taxable_value, TRY_TO_NUMBER(CGST) AS cgst, TRY_TO_NUMBER(SGST) AS sgst, TRY_TO_NUMBER(IGST) AS igst, TRY_TO_NUMBER(CESS) AS cess, \"Order Type\" AS order_type, \"Order Status\" AS order_status, \"Invoice Status\" AS invoice_status, \"Payment Mode\" AS payment_mode, \'SALES\' AS transaction_type, NULL AS credit_note_id, \"EE Invoice No\" AS ee_invoice_no FROM ANDAMEN_DB.MAPLEMONK.ANDAMEN_EASYECOM_TAX_SALES WHERE \"Order Type\" != \'STN\' AND \"Invoice Status\" != \'Cancelled\' AND \"Order Status\" != \'Cancelled\' ), returns_data AS ( SELECT TRY_TO_DATE(\"Invoice Date\", \'YYYY-MM-DD HH24:MI:SS\') AS transaction_date, TRY_TO_DATE(\"Return Date\", \'YYYY-MM-DD HH24:MI:SS\') AS return_date, \"MP Name\" AS marketplace_name, \"Sales Channel\" AS sales_channel, \"Component SKU Name\" AS product_name, \"Component SKU Brand\" AS brand, \"Component SKU Category\" AS category, \"Suborder No\" AS suborder_id, TRY_TO_NUMBER(\"Item Quantity\") AS quantity, TRY_TO_NUMBER(\"Component SKU MRP\") AS mrp, TRY_TO_NUMBER(\"Selling Price\") AS selling_price, TRY_TO_NUMBER(\"Component SKU Cost\") AS cost_price, TRY_TO_NUMBER(\"Taxable Value\") AS taxable_value, TRY_TO_NUMBER(CGST) AS cgst, TRY_TO_NUMBER(SGST) AS sgst, TRY_TO_NUMBER(IGST) AS igst, TRY_TO_NUMBER(CESS) AS cess, \"Order Type\" AS order_type, \"Order Status\" AS order_status, \"Invoice Status\" AS invoice_status, \"Payment Mode\" AS payment_mode, \'RETURN\' AS transaction_type, \"Credit Note ID\" AS credit_note_id, \"EE Invoice No\" AS ee_invoice_no FROM ANDAMEN_DB.MAPLEMONK.ANDAMEN_EASYECOM_TAX_RETURNS WHERE \"Order Type\" != \'STN\' AND \"Invoice Status\" != \'Cancelled\' AND \"Order Status\" != \'Cancelled\' ) SELECT transaction_date, return_date, marketplace_name, sales_channel, product_name, brand, category, suborder_id, CASE WHEN transaction_type = \'RETURN\' THEN -quantity ELSE quantity END AS quantity, mrp, selling_price, cost_price, CASE WHEN transaction_type = \'RETURN\' THEN -taxable_value ELSE taxable_value END AS taxable_value, CASE WHEN transaction_type = \'RETURN\' THEN -cgst ELSE cgst END AS cgst, CASE WHEN transaction_type = \'RETURN\' THEN -sgst ELSE sgst END AS sgst, CASE WHEN transaction_type = \'RETURN\' THEN -igst ELSE igst END AS igst, CASE WHEN transaction_type = \'RETURN\' THEN -cess ELSE cess END AS cess, order_type, order_status, invoice_status, payment_mode, transaction_type, credit_note_id, ee_invoice_no, CURRENT_TIMESTAMP() AS load_timestamp FROM ( SELECT * FROM sales_data UNION ALL SELECT * FROM returns_data ) ORDER BY transaction_date, transaction_type;",
                    "transaction": true
                }
            ) }}
            with sample_data as (

                select * from andamen_db.information_schema.databases
            ),
            
            final as (
                select * from sample_data
            )
            select * from final
            